import { test, expect } from '@playwright/test';

test.describe('File Upload Success Checkmark', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('/file-upload');
  });

  test('should display success checkmark when file is fully uploaded', async ({ page }) => {
    // Intercept the upload API call
    await page.route('**/api/upload', (route) => {
      route.continue();
    });

    // Locate and interact with file input using getByLabel
    const fileInput = page.getByLabel('Upload File');
    await fileInput.setInputFiles('fixtures/sample.pdf');

    // Wait for upload to complete
    await page.waitForResponse(response =>
      response.url().includes('/api/upload') && response.status() === 200
    );

    // Verify success message appears using getByRole
    const successMessage = page.getByRole('status');
    await expect(successMessage).toBeVisible();
    await expect(successMessage).toContainText('File uploaded successfully');

    // Verify success checkmark appears using getByRole
    const successCheckmark = page.getByRole('status');
    await expect(successCheckmark).toContainText('✓');

    // Verify file name is displayed using getByText
    const fileName = page.getByText('sample.pdf');
    await expect(fileName).toBeVisible();

    // Verify file size is displayed using getByText
    const fileSize = page.getByText('1.2 MB');
    await expect(fileSize).toBeVisible();

    // Verify upload button is disabled
    const uploadButton = page.getByRole('button', { name: /upload/i });
    await expect(uploadButton).toBeDisabled();
  });

  test('should not display success checkmark when upload fails', async ({ page }) => {
    // Intercept the upload API call with a failure response
    await page.route('**/api/upload', (route) => {
      route.abort('Failed to upload');
    });

    // Locate and interact with file input using getByLabel
    const fileInput = page.getByLabel('Upload File');
    await fileInput.setInputFiles('fixtures/nonexistent.pdf');

    // Wait for upload to fail
    await page.waitForResponse(response =>
      response.url().includes('/api/upload') && response.status() === 500
    );

    // Verify error message appears using getByRole
    const errorMessage = page.getByRole('status');
    await expect(errorMessage).toBeVisible();
    await expect(errorMessage).toContainText('Upload failed');

    // Verify success checkmark does not appear
    const successCheckmark = page.getByRole('status');
    await expect(successCheckmark).not.toContainText('✓');

    // Verify file name is not displayed
    const fileName = page.getByText('sample.pdf');
    await expect(fileName).not.toBeVisible();

    // Verify upload button is enabled
    const uploadButton = page.getByRole('button', { name: /upload/i });
    await expect(uploadButton).toBeEnabled();
  });
});
